#include "search/lra/LraPropagationEngine.h"
#include <array>
#include <chrono>
#include <cstdlib>
#include <fstream>
#include <optional>
#include <unordered_map>
using namespace xolver;
using Engine = LraPropagationEngine;
using Output = std::vector<Engine::ExplainedBound>;
extern "C" Output realPropagation(Engine*, const GeneralSimplex&, const PropagationBudget&,
    Engine::Statistics*, const Engine::BoundConsumer&) asm("__real_SYMBOL");
extern "C" Output observedPropagation(Engine*, const GeneralSimplex&, const PropagationBudget&,
    Engine::Statistics*, const Engine::BoundConsumer&) asm("__wrap_SYMBOL");
struct Previous {
    const GeneralSimplex* simplex = nullptr;
    std::optional<uint64_t> boundRevision, analysisRevision;
    std::vector<std::array<BoundInfo,2>> bounds;
    std::vector<std::string> names;
};
static bool sameBound(const BoundInfo& a, const BoundInfo& b) {
    return a.bound.kind == b.bound.kind && a.reason == b.reason &&
        (!a.bound.isFinite() || a.bound.value == b.bound.value);
}
extern "C" Output observedPropagation(Engine* engine, const GeneralSimplex& gs,
        const PropagationBudget& budget, Engine::Statistics* statistics,
        const Engine::BoundConsumer& consume) {
    static std::unordered_map<Engine*,Previous> previous;
    static size_t calls = 0;
    const size_t call = ++calls;
    const auto started = std::chrono::steady_clock::now();
    auto& prior = previous[engine];
    const bool comparable = prior.simplex == &gs && prior.bounds.size() == size_t(gs.numVars());
    const auto boundRevision = gs.boundRevision(), analysisRevision = gs.analysisRevision();
    const bool sameBoundRevision = comparable && boundRevision && boundRevision == prior.boundRevision;
    const bool sameAnalysisRevision = comparable && analysisRevision && analysisRevision == prior.analysisRevision;
    size_t changedVariables = 0, changedEndpoints = 0, changedNames = 0;
    std::vector<std::array<BoundInfo,2>> current;
    std::vector<std::string> names;
    current.reserve(gs.numVars()); names.reserve(gs.numVars());
    for (int var = 0; var < gs.numVars(); ++var) {
        const auto state = gs.varState(var);
        current.push_back({state.lower,state.upper}); names.push_back(state.name);
        if (!comparable) continue;
        const bool lower = !sameBound(current.back()[0],prior.bounds[var][0]);
        const bool upper = !sameBound(current.back()[1],prior.bounds[var][1]);
        changedVariables += lower || upper; changedEndpoints += size_t(lower) + size_t(upper);
        changedNames += names.back() != prior.names[var];
    }
    const char* destination = std::getenv("ARITH_STAGE_PROF");
    const auto observerUs = std::chrono::duration_cast<std::chrono::microseconds>(
        std::chrono::steady_clock::now()-started).count();
    if (destination) {
        std::ofstream log(std::string(destination)+".propagation.jsonl",std::ios::app);
        log << "{\"phase\":\"entry\",\"call\":" << call
            << ",\"variables\":" << gs.numVars() << ",\"rows\":" << gs.numRows()
            << ",\"comparable\":" << comparable << ",\"changed_variables\":" << changedVariables
            << ",\"changed_endpoints\":" << changedEndpoints << ",\"changed_names\":" << changedNames
            << ",\"same_bound_revision\":" << sameBoundRevision
            << ",\"same_analysis_revision\":" << sameAnalysisRevision
            << ",\"observer_microseconds\":" << observerUs << "}\n";
    }
    prior.simplex = &gs; prior.bounds = std::move(current); prior.names = std::move(names);
    prior.boundRevision = boundRevision; prior.analysisRevision = analysisRevision;
    Engine::Statistics observed;
    auto* collected = statistics ? statistics : &observed;
    const auto before = std::chrono::steady_clock::now();
    auto result = realPropagation(engine,gs,budget,collected,consume);
    if (destination) {
        const auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now()-before).count();
        std::ofstream log(std::string(destination)+".propagation.jsonl",std::ios::app);
        log << "{\"phase\":\"return\",\"call\":" << call << ",\"microseconds\":" << elapsed
            << ",\"derived\":" << result.size() << ",\"row_visits\":" << collected->rowVisits
            << ",\"snapshots\":" << collected->rowSnapshots << ",\"snapshot_hits\":" << collected->snapshotHits
            << ",\"unproductive\":" << collected->unproductiveSnapshots << "}\n";
    }
    return result;
}

