#include "search/lra/LraPropagationEngine.h"
#include "search/arith/ArithSolverBase.h"
#include "search/coordination/TheoryAtomRegistry.h"
#include <chrono>
#include <cstdlib>
#include <fstream>
using namespace xolver;
using Engine = LraPropagationEngine;
using Output = std::vector<Engine::ExplainedBound>;
static thread_local TheoryEffort currentEffort = TheoryEffort::Standard;
static thread_local size_t queries = 0, hits = 0;
extern "C" TheoryCheckResult realCheck(ArithSolverBase*, TheoryLemmaStorage&, TheoryEffort) asm("__real_CHECK_SYMBOL");
extern "C" TheoryCheckResult observedCheck(ArithSolverBase*, TheoryLemmaStorage&, TheoryEffort) asm("__wrap_CHECK_SYMBOL");
extern "C" TheoryCheckResult observedCheck(ArithSolverBase* solver, TheoryLemmaStorage& db, TheoryEffort effort) {
    const auto previous = currentEffort;
    currentEffort = effort;
    auto result = realCheck(solver,db,effort);
    currentEffort = previous;
    return result;
}
extern "C" std::optional<SatLit> realTarget(const TheoryAtomRegistry*, const LinearFormKey&, Relation,
    const mpq_class&, const std::function<bool(SatLit)>&) asm("__real_TARGET_SYMBOL");
extern "C" std::optional<SatLit> observedTarget(const TheoryAtomRegistry*, const LinearFormKey&, Relation,
    const mpq_class&, const std::function<bool(SatLit)>&) asm("__wrap_TARGET_SYMBOL");
extern "C" std::optional<SatLit> observedTarget(const TheoryAtomRegistry* registry, const LinearFormKey& lhs,
        Relation relation, const mpq_class& rhs, const std::function<bool(SatLit)>& accept) {
    ++queries;
    auto result = realTarget(registry,lhs,relation,rhs,accept);
    hits += result.has_value();
    return result;
}
extern "C" Output realPropagation(Engine*, const GeneralSimplex&, const PropagationBudget&,
    Engine::Statistics*, const Engine::BoundConsumer&) asm("__real_PROP_SYMBOL");
extern "C" Output observedPropagation(Engine*, const GeneralSimplex&, const PropagationBudget&,
    Engine::Statistics*, const Engine::BoundConsumer&) asm("__wrap_PROP_SYMBOL");
extern "C" Output observedPropagation(Engine* engine, const GeneralSimplex& gs,
        const PropagationBudget& budget, Engine::Statistics* statistics,
        const Engine::BoundConsumer& consume) {
    static size_t calls = 0;
    const auto call = ++calls;
    const auto before = std::chrono::steady_clock::now();
    const auto initialQueries = queries, initialHits = hits;
    Engine::Statistics observed;
    auto* collected = statistics ? statistics : &observed;
    auto result = realPropagation(engine,gs,budget,collected,consume);
    const char* destination = std::getenv("ARITH_STAGE_PROF");
    if (destination) {
        const auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now()-before).count();
        std::ofstream log(std::string(destination)+".propagation.jsonl",std::ios::app);
        log << "{\"phase\":\"return\",\"call\":" << call << ",\"microseconds\":" << elapsed
            << ",\"full_effort\":" << (currentEffort == TheoryEffort::Full)
            << ",\"variables\":" << gs.numVars() << ",\"rows\":" << gs.numRows()
            << ",\"derived\":" << result.size() << ",\"row_visits\":" << collected->rowVisits
            << ",\"snapshots\":" << collected->rowSnapshots << ",\"snapshot_hits\":" << collected->snapshotHits
            << ",\"unproductive\":" << collected->unproductiveSnapshots
            << ",\"queries\":" << queries-initialQueries << ",\"hits\":" << hits-initialHits << "}\n";
    }
    return result;
}
